'use strict';
const $=id=>document.getElementById(id), clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
const STORE='gyeongbuk-principal-population-v3:', META='gyeongbuk-principal-last';
let s=null, selected=null, toastTimer, effectTimer;
const schoolMap=new Map(SCHOOLS.map(x=>[x.id,x]));
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000)}
function initial(school){return {version:3,schoolId:school.id,base:school.base,year:2026,grades:school.grades.slice(),special:school.special,money:100,rep:50,teacher:60,happy:60,facilities:50,appeal:0,history:[],points:[{year:2026,total:school.base}],chosen:false,chosenIndex:null,done:false,last:`${school.name}의 교장으로 부임했습니다. 2026년 공시 학생 ${school.base.toLocaleString('ko-KR')}명에서 학교 이야기를 시작합니다.`}}
function loadSave(id){try{const v=JSON.parse(localStorage.getItem(STORE+id));if(!v||v.version!==3||v.schoolId!==id||!schoolMap.has(id)||!Array.isArray(v.grades)||v.grades.length!==6||!v.grades.every(x=>Number.isFinite(x)&&x>=0)||!Number.isFinite(v.special)||v.special<0||!Array.isArray(v.points)||!v.points.length||!v.points.every(p=>Number.isFinite(p.total)&&Number.isFinite(p.year))||!Array.isArray(v.history)||v.base!==schoolMap.get(id).base||v.year<2026||v.year>2045||!['money','rep','happy','teacher','facilities','appeal'].every(k=>Number.isFinite(v[k])))return null;return v}catch{return null}}
function persist(){try{localStorage.setItem(STORE+s.schoolId,JSON.stringify(s));localStorage.setItem(META,s.schoolId);return true}catch{return false}}
function listSchools(){const region=$('region').value,query=$('search').value.trim().replace(/\s/g,'').toLowerCase();const found=SCHOOLS.filter(x=>(!region||x.region===region)&&(!query||(x.name+x.region+x.address).replace(/\s/g,'').toLowerCase().includes(query)));$('resultCount').textContent=`총 ${found.length}개 학교·분교`;$('schoolList').innerHTML=found.length?found.map(x=>`<button class="school-option${selected?.id===x.id?' selected':''}" data-school="${esc(x.id)}" aria-pressed="${selected?.id===x.id}"><span>${esc(x.name)}</span><small>${esc(x.region)} ${selected?.id===x.id?'✓':'›'}</small></button>`).join(''):'<div class="no-results">검색 결과가 없습니다. 지역이나 학교명을 바꿔 보세요.</div>'}
function selectSchool(id){selected=schoolMap.get(id);if(!selected)return;const saved=loadSave(id);$('selectedInfo').innerHTML=`<b>🏫 ${esc(selected.name)}</b><small>${esc(selected.address)} · ${esc(selected.type)} · 2026년 공시</small>`;$('start').disabled=false;$('start').innerHTML=(saved?`${saved.year}년부터 이어하기`:'실제 학생 수로 교장 부임하기')+' <span>→</span>';const f30=PopulationModel.forecast(selected,2030),f45=PopulationModel.forecast(selected,2045);$('forecastPreview').innerHTML=`<div class="forecast-start"><span>2026년 공시 재학생</span><b>${selected.base.toLocaleString('ko-KR')}<small>명</small></b></div><div class="grade-chips">${selected.grades.map((v,i)=>`<span>${i+1}학년<b>${v}명</b></span>`).join('')}</div><small class="special-note">특수·순회학급 별도 집계 ${selected.special}명 포함</small><div class="forecast-future"><span>2030년 자체 추계<b>약 ${f30.total.toLocaleString('ko-KR')}명</b></span><span>2045년 자체 추계<b>약 ${f45.total.toLocaleString('ko-KR')}명</b></span></div><p class="history-note">공시 추이: ${Object.entries(selected.history).map(([y,n])=>y+'년 '+n.toLocaleString('ko-KR')+'명').join(' → ')}</p><p class="model-note">학교별 미래 값은 공시 학년 구성·최근 추세·경북 학령인구 전망으로 계산합니다. 교육청의 공식 학교별 예상 학생 수는 아닙니다.</p>`;listSchools()}
function showSetup(){if(s){persist();$('cancelSetup').hidden=false;selected=schoolMap.get(s.schoolId);$('region').value=selected.region;$('search').value='';selectSchool(selected.id)}$('setup').hidden=false;$('game').hidden=true;window.scrollTo({top:0,behavior:'instant'})}
function enterGame(){if(!selected)return;const saved=loadSave(selected.id);s=saved||initial(selected);$('setup').hidden=true;$('game').hidden=false;persist();render();const url=new URL(location.href);url.searchParams.set('school',s.schoolId);history.replaceState(null,'',url);window.scrollTo({top:0,behavior:'instant'});if(saved)notify(`${saved.year}년의 학교 이야기를 이어갑니다.`)}
function currentEvent(){return events[(s.year-2026)%events.length]}
function updateScene(){const total=PopulationModel.total(s.grades,s.special),ratio=total/s.base,eventIndex=(s.year-2026)%events.length;const rainy=eventIndex===5;$('scene').className='scene'+(rainy?' rain':'');$('season').textContent=['🌸 봄 학기','☀️ 여름 학기','🍁 가을 학기','❄️ 겨울 학기'][(s.year-2026)%4];$('mood').textContent=ratio<.45?'🏫 조용해진 교정':ratio<.8?'🌿 변화하는 학교':ratio>1.15?'🎉 북적이는 학교':'😊 활기찬 학교';$('schoolSign').textContent=schoolMap.get(s.schoolId).name;$('windows').innerHTML=Array.from({length:10},(_,i)=>`<div class="window ${i>=Math.ceil(ratio*8)?'off':''}"></div>`).join('');const n=Math.min(11,Math.max(2,Math.round(ratio*8)));$('yard').innerHTML=Array.from({length:n},(_,i)=>`<span class="person" style="left:${7+i*8}%;animation-duration:${.8+i*.12}s;animation-delay:${i*.1}s">${['🧒','👧','👦','🏃','👩‍🏫'][i%5]}</span>`).join('');let icons=['🚌','📚','💻','🏘️','🧸','☔','🎈','🤖'];let icon=s.chosen?(currentEvent().options[s.chosenIndex??0][3].match(/^\S+/)?.[0]||icons[eventIndex]):icons[eventIndex];$('situation').textContent=s.done?'🎓':icon;$('situation').className='situation '+(icon==='🚌'?'bus':'float')}
function animate(msg){const e=$('effect');e.textContent=msg.match(/^\S+/)?.[0]||'✨';e.classList.remove('play');void e.offsetWidth;e.classList.add('play');const icons=msg.startsWith('🌧')||msg.startsWith('☔')?['💧','🌧️']:['✨','⭐','🎊'];$('confetti').innerHTML=Array.from({length:18},(_,i)=>`<i style="left:${Math.random()*100}%;animation-delay:${Math.random()*.5}s">${icons[i%icons.length]}</i>`).join('');clearTimeout(effectTimer);effectTimer=setTimeout(()=>{$('confetti').innerHTML='';e.classList.remove('play')},2400)}
function render(){const school=schoolMap.get(s.schoolId),total=PopulationModel.total(s.grades,s.special),baseline=PopulationModel.forecast(school,s.year);document.title=`${school.name} · 교장 인생 시뮬레이터`;$('location').textContent=`경상북도 ${school.region} · 나의 학교 이야기`;$('schoolName').textContent=school.name;$('year').textContent=s.year;$('students').innerHTML=total.toLocaleString('ko-KR')+'<span>명</span>';$('money').textContent=s.money;$('rep').textContent=s.rep;$('career').textContent=`${s.year-2025}년차 교장`;$('studentDelta').textContent=s.points.length>1?`지난해보다 ${total-s.points[s.points.length-2].total>=0?'+':''}${total-s.points[s.points.length-2].total}명`:'새로운 시작';$('narrative').textContent=s.last;$('next').disabled=!s.chosen||s.done;$('step').textContent=s.done?'20년의 학교 운영을 마쳤습니다':s.chosen?'결정 완료 · 다음 해로 진행':'올해의 결정을 내리세요';$('decisionBadge').textContent=s.done?'운영 종료':s.chosen?'결정 완료 ✓':'선택 대기';$('yearProgress').style.width=((s.year-2026)/19*100)+'%';updateScene();$('metrics').innerHTML=[['학생 만족',s.happy],['교사 만족',s.teacher],['시설 수준',s.facilities],['학교 평판',s.rep]].map(([k,v])=>`<div class="metric"><div class="metric-top"><span>${k}</span><b>${v}<small> / 100</small></b></div><div class="bar"><div style="width:${v}%"></div></div></div>`).join('');$('historyCount').textContent=`${s.history.length}개의 기록`;$('history').innerHTML=s.history.slice().reverse().map(h=>`<div><b>${esc(h.year)}년</b>${esc(h.title)}</div>`).join('')||'아직 일지가 비어 있습니다. 첫 결정을 내려 보세요.';if(s.done){const score=Math.round(total*.35+s.rep*2+s.teacher+s.happy+s.facilities+s.money*.3);$('eventTitle').textContent='2045년, 당신이 남긴 학교';$('eventDesc').textContent=`최종 재학생 ${total}명 · 종합점수 ${score}점. ${total>baseline.total?'인구 기준선보다 많은 학생이 함께하는 학교를 만들었습니다!':total===baseline.total?'인구 변화 속에서 기준선 수준의 학교를 지켰습니다.':'인구 기준선과의 차이를 돌아보며 다음 학교 이야기를 준비해 보세요.'}`;$('choices').innerHTML='<button class="primary" id="endingRestart">새로운 교장 인생 시작 <span>↻</span></button>';$('endingRestart').onclick=reset}else{const ev=currentEvent();$('eventTitle').textContent=ev.title;$('eventDesc').textContent=ev.desc;$('choices').innerHTML=ev.options.map((o,i)=>`<button class="choice ${s.chosen&&s.chosenIndex===i?'picked':''}" ${s.chosen?'disabled':''} data-choice="${i}"><span class="number">${s.chosen&&s.chosenIndex===i?'✓':String(i+1).padStart(2,'0')}</span><span><b>${esc(o[0])}</b><small>${esc(o[1])}</small></span></button>`).join('')}updateForecast(school,total);draw()}
function choose(i){if(!s||s.chosen||s.done||!Number.isInteger(i)||i<0||i>2)return;const o=currentEvent().options[i];for(const[k,v]of Object.entries(o[2]))s[k]=k==='money'?Math.max(-50,s[k]+v):k==='appeal'?clamp(s[k]+v,-15,25):clamp(s[k]+v);s.chosen=true;s.chosenIndex=i;s.last=o[3];s.history.push({year:s.year,title:o[0]});render();animate(o[3]);if(!persist())notify('저장 공간이 부족합니다. 현재 플레이는 계속할 수 있습니다.')}
function advance(){if(!s||!s.chosen||s.done)return;const school=schoolMap.get(s.schoolId),old=PopulationModel.total(s.grades,s.special),previous=PopulationModel.forecast(school,s.year),next=PopulationModel.forecast(school,s.year+1),effects=PopulationModel.effects(s);s.grades=PopulationModel.transition(s.grades,previous,next,effects);s.special=next.special;s.year++;const total=PopulationModel.total(s.grades,s.special);s.money=clamp(s.money+Math.round(16+total/Math.max(1,s.base)*6)-Math.round(s.facilities*.035),-50,250);s.teacher=clamp(s.teacher-2);s.facilities=clamp(s.facilities-2);s.appeal=clamp(s.appeal-1,-15,25);s.points.push({year:s.year,total});const gap=total-next.total;s.last=`${s.year}년, ${total.toLocaleString('ko-KR')}명이 새 학년을 시작합니다. ${old>total?`지난해보다 ${old-total}명 감소.`:old<total?`지난해보다 ${total-old}명 증가.`:'지난해 학생 수 유지.'} 인구 기준선 ${next.total.toLocaleString('ko-KR')}명 대비 ${gap>=0?'+':''}${gap}명입니다.`;s.chosen=false;s.chosenIndex=null;s.done=s.year>=2045;render();animate(s.done?'🎓 교장 인생의 결말':'🎓 새로운 학년!');persist()}
function updateForecast(school,total){const base=PopulationModel.forecast(school,s.year),gap=total-base.total;const fx=PopulationModel.effects(s);$('comparison').innerHTML=`<span>인구 기준선<b>${base.total.toLocaleString('ko-KR')}명</b></span><span>내 선택의 차이<b class="${gap>=0?'positive':'negative'}">${gap>=0?'+':''}${gap.toLocaleString('ko-KR')}명</b></span>`;$('chartNote').textContent=`${s.year}년 기준 · 기준선은 자체 추계, 녹색 선은 게임 결과입니다. 현재 정책의 신입생 유입 효과 ${(fx.admission*100)>=0?'+':''}${(fx.admission*100).toFixed(1)}% (게임 가정).`;const played=new Map(s.points.map(p=>[p.year,p.total]));$('forecastTable').innerHTML='<table><thead><tr><th>연도</th><th>인구 기준선</th><th>내 학교</th><th>차이</th></tr></thead><tbody>'+school.forecast.map(p=>{const v=played.get(p.year),diff=v===undefined?null:v-p.total;return `<tr class="${p.year===s.year?'current':''}"><th>${p.year}${p.year===2026?' 공시':''}</th><td>${p.total.toLocaleString('ko-KR')}명</td><td>${v===undefined?'—':v.toLocaleString('ko-KR')+'명'}</td><td>${diff===null?'—':(diff>=0?'+':'')+diff+'명'}</td></tr>`}).join('')+'</tbody></table><p>2026년은 공시 값, 2027~2045년은 자체 추계. 미래의 내 학교 값은 게임을 진행하면 표시됩니다.</p>'}
function draw(){if(!s||$('game').hidden)return;const school=schoolMap.get(s.schoolId),c=$('chart'),r=c.getBoundingClientRect(),w=Math.max(200,r.width),h=r.height||155,d=Math.min(window.devicePixelRatio||1,3);c.width=w*d;c.height=h*d;const ctx=c.getContext('2d');if(!ctx)return;ctx.scale(d,d);ctx.clearRect(0,0,w,h);const arr=s.points,base=school.forecast,max=Math.max(1,...base.map(x=>x.total),...arr.map(x=>x.total))*1.12,left=39,right=w-14,top=14,bottom=h-24;ctx.strokeStyle='#e7eddf';ctx.fillStyle='#9caa8f';ctx.font='9px system-ui';for(let i=0;i<4;i++){const v=max*(1-i/3),y=top+(bottom-top)*i/3;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillText(Math.round(v).toLocaleString('ko-KR'),1,y+3)}const xx=y=>left+(y-2026)/19*(right-left),yy=v=>bottom-v/max*(bottom-top);ctx.strokeStyle='#a6aea0';ctx.lineWidth=1.7;ctx.setLineDash([4,4]);ctx.beginPath();base.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.stroke();ctx.setLineDash([]);ctx.beginPath();arr.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.lineTo(xx(arr.at(-1).year),bottom);ctx.lineTo(left,bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,bottom);gradient.addColorStop(0,'#79a66940');gradient.addColorStop(1,'#79a66900');ctx.fillStyle=gradient;ctx.fill();ctx.strokeStyle='#38764e';ctx.lineWidth=2.4;ctx.beginPath();arr.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.stroke();ctx.fillStyle='#96a387';[2026,2030,2035,2040,2045].forEach(y=>ctx.fillText(y,xx(y)-11,h-6));const last=arr.at(-1);ctx.fillStyle='#dcb65e';ctx.beginPath();ctx.arc(xx(last.year),yy(last.total),4,0,Math.PI*2);ctx.fill();c.setAttribute('aria-label',`회색 인구 기준선: ${base.map(p=>p.year+'년 약 '+p.total+'명').join(', ')}. 내 선택의 결과: ${arr.map(p=>p.year+'년 '+p.total+'명').join(', ')}`)}
function reset(){if(!s||!confirm(`${schoolMap.get(s.schoolId).name}의 인구 반영판 진행을 지우고 2026년 공시 값에서 다시 시작할까요?`))return;s=initial(schoolMap.get(s.schoolId));persist();render();notify('2026년 실제 공시 학생 수에서 다시 시작했습니다.')}
$('region').innerHTML+=[...new Set(SCHOOLS.map(x=>x.region))].sort((a,b)=>a.localeCompare(b,'ko')).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('schoolCount').textContent=SCHOOLS.length;$('region').onchange=listSchools;$('search').oninput=listSchools;$('schoolList').onclick=e=>{const b=e.target.closest('[data-school]');if(b)selectSchool(b.dataset.school)};$('choices').onclick=e=>{const b=e.target.closest('[data-choice]');if(b)choose(Number(b.dataset.choice))};$('start').onclick=enterGame;$('cancelSetup').onclick=()=>{if(s){$('setup').hidden=true;$('game').hidden=false;render();window.scrollTo({top:0,behavior:'instant'})}};$('switchSchool').onclick=showSetup;$('next').onclick=advance;$('restart').onclick=reset;$('save').onclick=()=>notify(persist()?'현재 기기에 진행 상황을 저장했습니다.':'진행 상황을 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.');addEventListener('resize',draw);addEventListener('pagehide',()=>{if(s)persist()});
let preferred=new URLSearchParams(location.search).get('school');if(!preferred){try{preferred=localStorage.getItem(META)}catch{}}if(preferred&&schoolMap.has(preferred)){selectSchool(preferred);$('region').value=selected.region}listSchools();
